const IMAGES = {
 "logo": "data:image/png;base64,",
 "lipstick": "data:image/png;base64,",
 "eyeshadow": "data:image/png;base64,",
 "cushion": "data:image/png;base64,",
 "mascara": "data:image/png;base64,",
 "eyebrow": "data:image/png;base64,",
 "blush": "data:image/png;base64,",
 "foundation": "data:image/png;base64,",
 "eyeliner": "data:image/png;base64,",
 "twoway": "data:image/png;base64,",
 "lipliner": "data:image/png;base64,",
 "contour": "data:image/png;base64,",
 "concealer": "data:image/png;base64,",
 "loosepowder": "data:image/png;base64,"
};

(function () {
  'use strict';

  var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function $(id) { return document.getElementById(id); }

  function applyImages(root) {
    (root || document).querySelectorAll('img[data-img]').forEach(function (img) {
      if (IMAGES[img.dataset.img] && !img.getAttribute('src')) img.src = IMAGES[img.dataset.img];
    });
  }

  var CATALOG = {
    cushion:     { name: 'Chusion',        price: 100000 },
    mascara:     { name: 'Mascara',        price: 72000 },
    eyeshadow:   { name: 'Eyeshadow',      price: 60000 },
    lipstick:    { name: 'Lipstick',       price: 50000 },
    eyeliner:    { name: 'Eyeliner',       price: 61600 },
    twoway:      { name: 'Two way cake',   price: 74432 },
    lipliner:    { name: 'Lip liner',      price: 39200 },
    contour:     { name: 'Contour',        price: 46400 },
    concealer:   { name: 'Concealer',      price: 100000 },
    loosepowder: { name: 'Loose powder',   price: 68720 },
    foundation:  { name: 'Foundation',     price: 150000 },
    eyebrow:     { name: 'Eyebrow pencil', price: 55000 }
  };
  
  var SEED_CART = [
    { id: 'foundation', qty: 1, price: 150000 },
    { id: 'eyebrow',    qty: 1, price: 55000 },
    { id: 'lipstick',   qty: 1, price: 55000 }
  ];
  var VOUCHERS = { RVGLOW: 0.10 };   

  var cart = copySeed();
  var voucher = null;                
  var order = null;                  
  var filters = { productGrid: { cat: 'all', q: '' }, discountGrid: { cat: 'all', q: '' } };

  function copySeed() { return SEED_CART.map(function (l) { return { id: l.id, qty: l.qty, price: l.price }; }); }
  function rp(n) { return 'Rp.' + String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '.'); }

  var toastTimer;
  function toast(msg) {
    var t = $('toast');
    t.textContent = msg;
    t.classList.add('show');
    clearTimeout(toastTimer);
    toastTimer = setTimeout(function () { t.classList.remove('show'); }, 2200);
  }

  function cartCount() { return cart.reduce(function (s, l) { return s + l.qty; }, 0); }
  function cartSubtotal() { return cart.reduce(function (s, l) { return s + l.qty * l.price; }, 0); }
  function cartTotal() {
    var sub = cartSubtotal();
    return voucher ? Math.round(sub * (1 - voucher.rate)) : sub;
  }

  function updateBadges(bump) {
    var n = cartCount();
    document.querySelectorAll('[data-cart-count]').forEach(function (el) {
      el.textContent = n;
      el.hidden = n === 0;
      if (bump) {
        el.classList.remove('bump');
        void el.offsetWidth;            
        el.classList.add('bump');
      }
    });
  }

  function addToCart(id, btn) {
    var p = CATALOG[id];
    if (!p) return;
    var line = cart.filter(function (l) { return l.id === id; })[0];
    if (line) line.qty += 1; else cart.push({ id: id, qty: 1, price: p.price });
    updateBadges(true);
    renderCart();
    toast(p.name + ' added to cart');
    if (btn && btn.classList.contains('add')) {
      var label = btn.querySelector('span');
      btn.classList.add('is-added');
      if (label) label.textContent = 'Added';
      setTimeout(function () {
        btn.classList.remove('is-added');
        if (label) label.textContent = 'Add to cart';
      }, 1200);
    }
  }

  function cartAction(btn) {
    var row = btn.closest('.item');
    if (!row) return;
    var id = row.dataset.id;
    var line = cart.filter(function (l) { return l.id === id; })[0];
    if (!line) return;
    var act = btn.dataset.act;
    if (act === 'inc') line.qty += 1;
    if (act === 'dec') line.qty -= 1;
    if (act === 'remove') line.qty = 0;
    if (line.qty < 1) cart = cart.filter(function (l) { return l !== line; });
    updateBadges(true);
    renderCart();
  }

  function itemHtml(l) {
    var p = CATALOG[l.id];
    return '<div class="item" data-id="' + l.id + '">' +
      '<div class="pic"><img src="' + IMAGES[l.id] + '" alt="' + p.name + '"></div>' +
      '<div class="item-body"><span class="tag name">' + p.name + '</span><br><span class="tag price">' + rp(l.price) + '</span>' +
        '<div class="qty" role="group" aria-label="Jumlah ' + p.name + '">' +
          '<button type="button" data-act="dec" aria-label="Kurangi jumlah"><svg class="i"><use href="#i-minus"/></svg></button>' +
          '<span>' + l.qty + '</span>' +
          '<button type="button" data-act="inc" aria-label="Tambah jumlah"><svg class="i"><use href="#i-plus"/></svg></button>' +
        '</div></div>' +
      '<button type="button" class="remove" data-act="remove" aria-label="Hapus ' + p.name + '"><svg class="i"><use href="#i-trash"/></svg></button>' +
      '</div>';
  }

  function renderCart() {
    var box = $('cartItems');
    if (!box) return;
    var empty = cart.length === 0;
    box.innerHTML = empty
      ? '<div class="cart-empty"><svg class="i"><use href="#i-cart"/></svg><p>Your cart is empty.</p><button type="button" class="btn" data-go="product">Shop now</button></div>'
      : cart.map(itemHtml).join('');
    $('voucherBox').hidden = empty;
    $('placeOrder').hidden = empty;
    $('sumTotal').hidden = empty;
    $('sumNote').hidden = empty;
    if (empty) { voucher = null; $('voucherMsg').textContent = ''; return; }

    $('sumTotal').textContent = 'Total item(s)=' + rp(cartTotal());
    var note = cartCount() + (cartCount() === 1 ? ' item' : ' items') + ' · Shipping: free';
    if (voucher) note += ' · Voucher ' + voucher.code + ' (-' + Math.round(voucher.rate * 100) + '%)';
    $('sumNote').textContent = note;
  }

  function applyFilters(gridId) {
    var f = filters[gridId];
    var shown = 0;
    document.querySelectorAll('#' + gridId + ' .prod').forEach(function (card) {
      var name = card.querySelector('.name').textContent.toLowerCase();
      var ok = (f.cat === 'all' || card.dataset.cat === f.cat) && name.indexOf(f.q) !== -1;
      card.hidden = !ok;
      if (ok) shown += 1;
    });
    var empty = document.querySelector('[data-empty="' + gridId + '"]');
    var count = document.querySelector('[data-count="' + gridId + '"]');
    if (empty) empty.hidden = shown > 0;
    if (count) count.textContent = shown + (shown === 1 ? ' product' : ' products');
  }

  function setCategory(gridId, cat) {
    filters[gridId].cat = cat;
    document.querySelectorAll('.chips[data-for="' + gridId + '"] .chip').forEach(function (c) {
      c.setAttribute('aria-pressed', c.dataset.cat === cat ? 'true' : 'false');
    });
    applyFilters(gridId);
  }

  function initSlider(root) {
    var track = root.querySelector('.slides');
    var slides = Array.prototype.slice.call(track.children);
    var dots = Array.prototype.slice.call(root.querySelectorAll('.dot'));
    var index = 0, timer = null;

    function set(n) {
      index = (n + slides.length) % slides.length;
      track.style.transform = 'translateX(-' + (index * 100) + '%)';
      slides.forEach(function (s, k) { s.inert = k !== index; s.setAttribute('aria-hidden', k === index ? 'false' : 'true'); });
      dots.forEach(function (d, k) { d.setAttribute('aria-current', k === index ? 'true' : 'false'); });
    }
    function stop() { clearInterval(timer); timer = null; }
    function play() {
      if (reduceMotion) return;
      stop();
      timer = setInterval(function () {
        if ($('home').classList.contains('active')) set(index + 1);   /* hanya berjalan di Home */
      }, 5000);
    }

    dots.forEach(function (d, k) { d.addEventListener('click', function () { set(k); play(); }); });
    root.addEventListener('mouseenter', stop);
    root.addEventListener('mouseleave', play);
    root.addEventListener('focusin', stop);
    root.addEventListener('focusout', play);

    var startX = null;                              /* geser dengan jari */
    root.addEventListener('touchstart', function (e) { startX = e.touches[0].clientX; }, { passive: true });
    root.addEventListener('touchend', function (e) {
      if (startX === null) return;
      var dx = e.changedTouches[0].clientX - startX;
      if (Math.abs(dx) > 40) { set(index + (dx < 0 ? 1 : -1)); play(); }
      startX = null;
    }, { passive: true });

    set(0);
    play();
  }

  function two(n) { return (n < 10 ? '0' : '') + n; }
  function tickCountdown() {
    var now = new Date();
    var end = new Date(now);
    end.setHours(24, 0, 0, 0);
    var s = Math.max(0, Math.floor((end - now) / 1000));
    var html = '<b>' + two(Math.floor(s / 3600)) + '</b><i>:</i><b>' + two(Math.floor(s % 3600 / 60)) + '</b><i>:</i><b>' + two(s % 60) + '</b>';
    document.querySelectorAll('[data-countdown]').forEach(function (el) { el.innerHTML = html; });
  }

  function renderFooters() {
    var year = new Date().getFullYear();
    document.querySelectorAll('[data-footer]').forEach(function (f) {
      f.innerHTML =
        '<div class="f-brand"><img data-img="logo" alt=""><div><div class="brand">rv<br>cosmetics</div><p>Everyday makeup, made easy.</p></div></div>' +
        '<nav class="f-links" aria-label="Footer">' +
          '<button type="button" data-go="product">Product</button>' +
          '<button type="button" data-go="discount">Discount</button>' +
          '<button type="button" data-go="order">My order</button>' +
        '</nav>' +
        '<p class="f-note">&copy; ' + year + ' RV Cosmetics. Demo website.</p>';
    });
    applyImages();
  }

  function show(id) {
    if (!$(id)) id = 'login';
    if (id === 'personal' && cart.length === 0) { id = 'order'; toast('Your cart is empty.'); }

    document.querySelectorAll('.screen').forEach(function (s) { s.classList.remove('active'); });
    $(id).classList.add('active');
    if (id === 'home') $('home').classList.remove('menu-closed');
    if (id === 'order') renderCart();
    if (id === 'personal') fillMiniSummary();
    if (id === 'success') fillSuccess();
    window.scrollTo(0, 0);
  }
  function go(id) {
    if (location.hash === '#' + id) show(id); else location.hash = id;
  }
  window.addEventListener('hashchange', function () { show(location.hash.slice(1) || 'login'); });

  document.addEventListener('click', function (e) {
    var t = e.target, el;

    if ((el = t.closest('[data-toast]'))) { toast(el.dataset.toast); return; }
    if ((el = t.closest('[data-add]'))) { addToCart(el.dataset.add, el); return; }
    if ((el = t.closest('[data-act]'))) { cartAction(el); return; }
    if ((el = t.closest('.chip[data-target]'))) { setCategory(el.dataset.target, el.dataset.cat); return; }
    if ((el = t.closest('[data-home-cat]'))) { setCategory('productGrid', el.dataset.homeCat); go('product'); return; }
    if ((el = t.closest('[data-toggle-pw]'))) {
      var input = $(el.dataset.togglePw);
      var hide = input.type === 'password';
      input.type = hide ? 'text' : 'password';
      el.setAttribute('aria-label', hide ? 'Hide password' : 'Show password');
      el.querySelector('use').setAttribute('href', hide ? '#i-eye-off' : '#i-eye');
      return;
    }
    if (t.closest('[data-toggle-menu]')) { $('home').classList.toggle('menu-closed'); return; }
    if ((el = t.closest('[data-go]'))) {
      e.preventDefault();
      if (el.hasAttribute('data-reset')) resetDemo();
      go(el.dataset.go);
      if (el.dataset.focus) setTimeout(function () { var f = $(el.dataset.focus); if (f) f.focus(); }, 60);
    }
  });

  document.querySelectorAll('[data-filter]').forEach(function (input) {
    input.addEventListener('input', function () {
      filters[input.dataset.filter].q = input.value.trim().toLowerCase();
      applyFilters(input.dataset.filter);
    });
  });

  $('loginForm').addEventListener('submit', function (e) { e.preventDefault(); go('home'); });

  function applyVoucher() {
    var code = $('voucherInput').value.trim().toUpperCase();
    var msg = $('voucherMsg');
    if (!code) { msg.className = 'voucher-msg bad'; msg.textContent = 'Please enter a voucher code.'; return; }
    if (VOUCHERS[code]) {
      voucher = { code: code, rate: VOUCHERS[code] };
      msg.className = 'voucher-msg ok';
      msg.textContent = 'Voucher applied: ' + Math.round(voucher.rate * 100) + '% off.';
      renderCart();
    } else {
      voucher = null;
      msg.className = 'voucher-msg bad';
      msg.textContent = 'This voucher code is not valid.';
      renderCart();
    }
  }
  $('applyVoucher').addEventListener('click', applyVoucher);
  $('voucherInput').addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); applyVoucher(); } });

  function fillMiniSummary() {
    var n = cartCount();
    $('miniCount').textContent = n + (n === 1 ? ' item' : ' items') + (voucher ? ' · voucher ' + voucher.code : '');
    $('miniTotal').textContent = rp(cartTotal());
  }

  $('detailsForm').addEventListener('submit', function (e) {
    e.preventDefault();
    var name = $('f-name'), phone = $('f-phone'), err = $('formError');
    var okName = name.value.trim().length >= 2;
    var okPhone = phone.value.replace(/\D/g, '').length >= 8;
    name.setAttribute('aria-invalid', okName ? 'false' : 'true');
    phone.setAttribute('aria-invalid', okPhone ? 'false' : 'true');
    if (!okName || !okPhone) {
      err.textContent = !okName && !okPhone ? 'Please enter your full name and a phone number with at least 8 digits.'
        : !okName ? 'Please enter your full name.' : 'Please enter a phone number with at least 8 digits.';
      (okName ? phone : name).focus();
      return;
    }
    err.textContent = '';
    order = makeOrder(name.value.trim());
    go('success');
  });
  ['f-name', 'f-phone'].forEach(function (id) {
    $(id).addEventListener('input', function () { this.setAttribute('aria-invalid', 'false'); $('formError').textContent = ''; });
  });

  function makeOrder(name) {
    var d = new Date();
    var no = 'RV' + String(d.getFullYear()).slice(2) + two(d.getMonth() + 1) + two(d.getDate()) + String(Math.floor(1000 + Math.random() * 9000));
    var payEl = document.querySelector('input[name="pay"]:checked');
    return {
      no: no,
      name: name || '',
      pay: payEl ? payEl.value : 'Cash on delivery',
      total: cartTotal(),
      items: cart.map(function (l) { return { name: CATALOG[l.id].name, qty: l.qty, price: l.price }; })
    };
  }

  function fillSuccess() {
    if (!order) order = makeOrder('');                   
    $('orderNo').textContent = order.no;
    $('orderPay').textContent = order.pay;
    $('orderTotal').textContent = rp(order.total);
    $('thanks').textContent = order.name ? 'Thank you, ' + order.name.split(' ')[0] + '!' : 'Thank you for shopping with us.';
    $('orderList').innerHTML = order.items.map(function (i) {
      return '<li><span>' + i.name + ' x ' + i.qty + '</span><span>' + rp(i.price * i.qty) + '</span></li>';
    }).join('');
    burst();
  }

  function burst() {
    if (reduceMotion) return;
    var old = document.querySelector('.confetti');
    if (old) old.remove();
    var box = document.createElement('div');
    box.className = 'confetti';
    box.setAttribute('aria-hidden', 'true');
    var colors = ['#FFC6C6', '#F3A5A5', '#E8211F', '#F9DCDA', '#111'];
    for (var i = 0; i < 56; i++) {
      var p = document.createElement('i');
      p.style.left = Math.random() * 100 + '%';
      p.style.background = colors[i % colors.length];
      p.style.animationDuration = (2.2 + Math.random() * 2) + 's';
      p.style.animationDelay = (Math.random() * 0.6) + 's';
      p.style.setProperty('--dx', (Math.random() * 120 - 60) + 'px');
      p.style.setProperty('--rot', (360 + Math.random() * 540) + 'deg');
      box.appendChild(p);
    }
    document.body.appendChild(box);
    setTimeout(function () { box.remove(); }, 5200);
  }

  function resetDemo() {
    cart = copySeed();
    voucher = null;
    order = null;
    $('voucherInput').value = '';
    $('voucherMsg').textContent = '';
    ['f-name', 'f-phone', 'f-area', 'f-street', 'f-other'].forEach(function (id) { $(id).value = ''; $(id).setAttribute('aria-invalid', 'false'); });
    $('formError').textContent = '';
    updateBadges(false);
    renderCart();
  }

  renderFooters();
  applyImages();
  renderCart();
  updateBadges(false);
  applyFilters('productGrid');
  applyFilters('discountGrid');
  document.querySelectorAll('[data-slider]').forEach(initSlider);
  tickCountdown();
  setInterval(tickCountdown, 1000);
  show(location.hash.slice(1) || 'login');
})();
